def seval(expr: str) -> float:
    import re
    tokens = re.findall(r'\(|\)|[^\s()]+', expr)

    def parse(tokens_iter):
        token = next(tokens_iter)
        if token != '(':
            # atom: number or variable
            if re.fullmatch(r'-?\d+(?:\.\d+)?', token):
                return float(token)
            return token  # variable name
        # '(' encountered: look ahead
        token = next(tokens_iter)
        if token == 'let':
            # parse bindings list
            next(tokens_iter)  # '(' starting bindings list
            bindings = []
            while True:
                t = next(tokens_iter)
                if t == ')':
                    break
                # t is '(' starting a binding
                var = next(tokens_iter)          # variable name
                val = parse(tokens_iter)         # value expression
                next(tokens_iter)                # ')'
                bindings.append((var, val))
            body = parse(tokens_iter)            # body expression
            next(tokens_iter)                    # ')'
            return ('let', bindings, body)
        else:
            # operator form
            op = token
            args = []
            while True:
                peek = next(tokens_iter)
                if peek == ')':
                    break
                # push back peek
                tokens_iter = prepend(peek, tokens_iter)
                args.append(parse(tokens_iter))
            return (op, args)

    # helper to prepend a single token back onto an iterator
    def prepend(value, iterator):
        yield value
        yield from iterator

    # Build AST
    ast = parse(iter(tokens))

    # Evaluation with environment stack
    def eval_ast(node, env):
        if isinstance(node, float):
            return node
        if isinstance(node, str):
            # variable lookup
            for scope in reversed(env):
                if node in scope:
                    return scope[node]
            raise NameError(f"Unbound variable: {node}")
        if node[0] == 'let':
            _, bindings, body = node
            new_scope = {}
            # sequentially evaluate bindings, allowing later ones to see earlier ones
            for var, val_expr in bindings:
                val = eval_ast(val_expr, env + [new_scope])
                new_scope[var] = val
            return eval_ast(body, env + [new_scope])
        else:
            op, args = node
            evaled = [eval_ast(arg, env) for arg in args]
            if op == '+':
                return sum(evaled)
            if op == '*':
                prod = 1.0
                for v in evaled:
                    prod *= v
                return prod
            if op == '-':
                if len(evaled) == 1:
                    return -evaled[0]
                return evaled[0] - sum(evaled[1:])
            if op == '/':
