        ('MUL',   r'\*'),           # Multiplication
        ('DIV',   r'/'),            # Division
        ('LP',    r'\('),           # Left parenthesis
        ('RP',    r'\)'),           # Right parenthesis
        ('SKIP',  r'\s+'),          # Skip whitespace
    ]
