    tokens = [(m.lastgroup, m.group()) for m in re.finditer(tok_regex, expr) if m.lastgroup != 'SKIP']

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def consume(expected=None):
        nonlocal pos
        if pos >= len(tokens):
