    ops = {
        '+': lambda *args: sum(args),
        '*': lambda *args: math.prod(args),
        '-': lambda *args: -args[0] if len(args) == 1 else args[0] - sum(args[1:]),
        '/': lambda *args: args[0] / args[1] if len(args) == 2
